import{_ as n,o as a,c as i,ah as s}from"./chunks/framework.QnJvYzEf.js";const r="/projects/TurboPi/en/advanced/assets/image3.vqeITqpf.jpeg",c="/projects/TurboPi/en/advanced/assets/image4.BGIIj1iQ.jpeg",l="/projects/TurboPi/en/advanced/assets/image5.CCgHJijY.jpeg",o="/projects/TurboPi/en/advanced/assets/image6.D0H3u9si.jpeg",t="/projects/TurboPi/en/advanced/assets/image7.DU5uGdZJ.jpeg",d="data:image/png;base64,",p="/projects/TurboPi/en/advanced/assets/image9.BZXmJbxo.jpeg",g="/projects/TurboPi/en/advanced/assets/image10.CiZ6D0uM.jpeg",h="/projects/TurboPi/en/advanced/assets/image11.D7c4J9S8.jpeg",u="/projects/TurboPi/en/advanced/assets/image12.BHm68kg2.jpeg",m="/projects/TurboPi/en/advanced/assets/image14.YrQCrvnq.jpeg",b="/projects/TurboPi/en/advanced/assets/image13.DyyxYLW4.jpeg",P="/projects/TurboPi/en/advanced/assets/image5.CCgHJijY.jpeg",y="/projects/TurboPi/en/advanced/assets/image18.DwlqJ4kA.jpeg",q="/projects/TurboPi/en/advanced/assets/image19.DMFOKP84.jpeg",w="/projects/TurboPi/en/advanced/assets/image20.B_J8UPmx.jpeg",v="/projects/TurboPi/en/advanced/assets/image10.CiZ6D0uM.jpeg",A="/projects/TurboPi/en/advanced/assets/image2.K-5gVnRF.png",_="/projects/TurboPi/en/advanced/assets/image3.B_RMM1fJ.png",T="/projects/TurboPi/en/advanced/assets/image4.BEgZMht4.png",f="/projects/TurboPi/en/advanced/assets/image5.D54FtYft.png",k="/projects/TurboPi/en/advanced/assets/image6.B4cJbbBt.png",j="/projects/TurboPi/en/advanced/assets/image7.BVRmHdXT.png",C="/projects/TurboPi/en/advanced/assets/image8.BE4scRrR.png",x="/projects/TurboPi/en/advanced/assets/image9.CclOqOz8.png",M="/projects/TurboPi/en/advanced/assets/image10.sSrQLO4-.png",z="/projects/TurboPi/en/advanced/assets/image11.Uil1o0_l.png",W="/projects/TurboPi/en/advanced/assets/image12.BzykNai0.png",J=JSON.parse('{"title":"2. Quick User Experience","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2.quick_user_experience.md","filePath":"docs/2.quick_user_experience.md"}'),B={name:"docs/2.quick_user_experience.md"};function O(F,e,I,Q,S,E){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="_2-quick-user-experience" tabindex="-1">2. Quick User Experience <a class="header-anchor" href="#_2-quick-user-experience" aria-label="Permalink to &quot;2. Quick User Experience&quot;">​</a></h1><p id="anchor_2_1"></p><h2 id="_2-1-app-installation-and-connection" tabindex="-1">2.1 APP Installation and Connection <a class="header-anchor" href="#_2-1-app-installation-and-connection" aria-label="Permalink to &quot;2.1 APP Installation and Connection&quot;">​</a></h2><p>This lesson will introduce how to install the app on your phone and connect it to your TurboPi.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>① Please grant all permissions requested during installation to ensure the app functions properly.</p><p>② Make sure your phone&#39;s location services (GPS) and Wi-Fi are enabled before launching the app.</p></section><h3 id="_2-1-1-installation" tabindex="-1">2.1.1 Installation <a class="header-anchor" href="#_2-1-1-installation" aria-label="Permalink to &quot;2.1.1 Installation&quot;">​</a></h3><p>For Android devices:<strong><a href="https://play.google.com/store/apps/details?id=com.Wonder.Pi" target="_blank" rel="noreferrer">APP Installation Pack (Android)</a></strong></p><p>For iOS devices : Go to the App Store, search for &quot;<a href="https://apps.apple.com/cn/app/wonderpi/id1477946178" target="_blank" rel="noreferrer"><strong>WonderPi</strong></a>&quot;, and download the app.</p><p>The WonderPi app is used to control the TurboPi robot. In this lesson, we&#39;ll guide you through how to connect TurboPi with the app.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li><p>Before connecting, make sure TurboPi is powered on.</p></li><li><p>Turn on your phone&#39;s GPS and Wi-Fi before opening the app.</p></li><li><p>This guide uses an Android device as an example; the steps are similar for iOS.</p></li></ul></section><h3 id="_2-1-2-app-connection" tabindex="-1">2.1.2 APP Connection <a class="header-anchor" href="#_2-1-2-app-connection" aria-label="Permalink to &quot;2.1.2 APP Connection&quot;">​</a></h3><p>(1) Turn on the power switch on the Raspberry Pi expansion board to start TurboPi. For detailed steps, refer to: &quot;<a href="./1.getting_ready.html#charging-and-power-on-status-description"><strong>Read First\\1.6 Charging and Power-On Status Explanation</strong></a>&quot;.</p><p>(2) Once TurboPi is successfully powered on, it will enter AP (Access Point) Mode and create a Wi-Fi hotspot beginning with <strong>&quot;HW&quot;</strong>.</p><ul><li><strong>Connection Modes Overview</strong></li></ul><p>There are two connection modes, namely direct connection mode and LAN mode. APP functions are the same under these two modes.</p><p>(1) AP direct connection mode: TurboPi creates a hotspot that your phone can connect to directly, but no Internet access in this mode.</p><p>(2) STA LAN mode: TurboPi connects to a specified Wi-Fi network, and Internet access is available in this mode.</p><ul><li><strong>Connecting in AP Mode (Recommended First Step)</strong></li></ul><p>When TurboPi powers on, it automatically enters AP mode and broadcasts a hotspot starting with &quot;<strong>HW</strong>&quot;.</p><p>(1) Open the WonderPi app and select <strong>&quot;Basic&quot; &gt; &quot;TurboPi&quot;</strong>.</p><img loading="lazy" height="577" width="1120" src="'+r+'"><p>(2) Tap <strong>&quot;+&quot;</strong> in bottom right corner, and then select <strong>Direct Connection Mode</strong>.</p><img loading="lazy" src="'+c+'"><p>(3) Tap <strong>&quot;Go to connect device hotspots&quot;</strong>, which will take you to the Wi-Fi settings page. Find the Wi-Fi hotspot that starts with <strong>&quot;HW&quot;</strong> and connect to it by entering the password: <strong>hiwonder.</strong></p><img loading="lazy" src="'+l+'"><img loading="lazy" src="'+o+'" style="width:350px;" class="common_img"><p>(4) After connecting, return to the WonderPi app.</p><img loading="lazy" src="'+t+'" style="width:350px;" class="common_img"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>For iOS users: Make sure the Wi-Fi icon appears in the status bar before switching back to the app, or the device might not be detected. If the app doesn&#39;t detect the device right away, tap the refresh icon <img loading="lazy" height="52" width="52" src="'+d+'" style="width:45px;"> in the upper-right corner.</p></section><p>(5) Once the app connects to TurboPi, you&#39;ll see an icon like the one below indicating a successful connection.</p><img loading="lazy" src="'+p+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>if you are informed of &quot;No Internet. Whether to keep connection&quot;, just select &quot;<strong>keep connected</strong>&quot;.</p></section><p>(6) Tap robot icon to enter mode selection interface.</p><img loading="lazy" src="'+g+'"><p>For detailed instructions on each play mode, refer to: &quot;<strong><a href="#anchor_2_2">2.2 Play Modes in the App</a></strong>&quot;.</p><ul><li><strong>Connecting in LAN Mode (STA Mode</strong>)</li></ul><p>(1) First, disconnect from TurboPi&#39;s AP mode hotspot and connect your phone to a Wi-Fi network. For example, connect to a network named <strong>&quot;Hiwonder&quot;</strong>.</p><img loading="lazy" src="'+h+'" style="width:350px;" class="common_img"><p>(2) After connection, open <strong>&quot;WonderPi&quot;</strong>. Select <strong>&quot;Standard -&gt;TurboPi&quot;</strong> in sequence.</p><img loading="lazy" src="'+u+'"><p>(3) Tap &quot;<strong>+</strong>&quot; in bottom right corner, and then select LAN Mode.</p><img loading="lazy" src="'+m+'"><p>(4) The app will prompt you to enter the Wi-Fi password for the network you&#39;re connected to. Make sure you enter the correct password, a wrong password will prevent the connection. After entering the password, tap <strong>&quot;OK&quot;</strong>.</p><img loading="lazy" src="'+b+'"><p>(5) Tap &quot;<strong>Go to connect device hotspot</strong>&quot; to switch to the Wi-Fi settings.</p><img loading="lazy" src="'+P+'"><p>(6) Connect to the TurboPi hotspot (starting with &quot;<strong>HW</strong>&quot;) using the password hiwonder. After connecting, return to the WonderPi app.</p><img loading="lazy" src="'+o+'" style="width:48%;"><img loading="lazy" src="'+t+'" style="width:48%;"><p>(7) It will begin configuring the network automatically.</p><img loading="lazy" src="'+y+'"><p>(8) Wait a few seconds. Once the TurboPi icon appears on the main screen and the LED on the expansion board stays on, the setup is complete.</p><img loading="lazy" src="'+q+'"><p>(9) Long-press the TurboPi icon in the app to view its assigned IP address and Device ID.</p><img loading="lazy" src="'+w+'"><p>(10) Tap the TurboPi icon to access the play mode menu.</p><img loading="lazy" src="'+v+'"><p>For detailed introduction to robot games, please refer to the file in&quot;<strong>2.2 Play Modes in the App</strong>&quot;.</p><p id="anchor_2_2"></p><h2 id="_2-2-play-modes-in-the-app" tabindex="-1">2.2 Play Modes in the App <a class="header-anchor" href="#_2-2-play-modes-in-the-app" aria-label="Permalink to &quot;2.2 Play Modes in the App&quot;">​</a></h2><h3 id="_2-2-1-getting-started" tabindex="-1">2.2.1 Getting Started <a class="header-anchor" href="#_2-2-1-getting-started" aria-label="Permalink to &quot;2.2.1 Getting Started&quot;">​</a></h3><p>Before getting started, make sure TurboPi is powered on.</p><p>Follow the tutorial in <a href="./1.getting_ready.html#adjust-pan-tilt">1.Read First-&gt;1.9 Pan-Tilt Adjustment</a> to calibrate the pan-tilt servo&#39;s position and eliminate any deviation.</p><p>Then, refer to <a href="#anchor_2_1">2.1.1 Installation</a> to install the WonderPi mobile app and connect it to your TurboPi.</p><h3 id="_2-2-2-start-exploring-play-modes" tabindex="-1">2.2.2 Start Exploring Play Modes <a class="header-anchor" href="#_2-2-2-start-exploring-play-modes" aria-label="Permalink to &quot;2.2.2 Start Exploring Play Modes&quot;">​</a></h3><p>Once the connection is successful, tap the TurboPi icon to enter the mode selection screen. Tap any icon on the screen to enter the corresponding play mode.</p><ul><li><strong>Robot Control</strong></li></ul><p>Tap <strong>&quot;Robot Control&quot;</strong> to enter this mode. The robot will automatically reset to its default posture.</p><img loading="lazy" height="385" width="748" class="common_img" src="'+A+'"><p>This interface is divided into three sections:</p><p>(1) Left Panel – Movement Controls: Use the virtual joystick to control the robot&#39;s movements.</p><p>(2) Center Panel – Video Feed &amp; Pan-tilt Control: The center displays the real-time camera feed. You can swipe on the screen to adjust the camera angle.</p><p>(3) Right Panel – Ultrasonic RGB Light Control: Use the slider to change the RGB lighting status of the ultrasonic sensor module.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The camera Pan-tilt has movement limits. If you reach the limit and continue swiping in the same direction, the phone will give haptic feedback. Please stop swiping in that direction.</p></section><ul><li><strong>Target Tracking</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li><p>The selected color range should be appropriate—not too large or too small. A range that&#39;s too wide may include unwanted colors, while too narrow may cause the robot to lose track of the target.</p></li><li><p>MAvoid having objects with colors similar to the target in the camera view.</p></li></ul></section><p>(1) Tap <strong>&quot;Pan-tilt Tracking&quot;</strong> to enter the mode. In this mode, the robot car will follow an object based on its color.</p><img loading="lazy" height="390" width="749" class="common_img" src="'+_+'"><p>(2) Drag the red circle in the live camera feed to the object you want to track. Tap &quot;<strong>Confirm Color</strong>&quot; to set the target color.</p><img loading="lazy" height="384" width="749" class="common_img" src="'+T+'"><p>(3) The selected color will be displayed under &quot;<strong>Tracking Color</strong>&quot;.</p><img loading="lazy" height="387" width="749" class="common_img" src="'+f+'"><p>(4) Choose a tracking mode, then start the feature. When the target object moves, the robot will follow it.</p><img loading="lazy" height="385" width="751" class="common_img" src="'+k+'"><ul><li><strong>Color-Based Line Following</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li>You can use colored tape to create a track.</li><li>Choose a color range that is not too wide or too narrow. Also, make sure no similar colors appear in the camera view.</li></ul></section><p>(1) Tap <strong>&quot;Start Following&quot;</strong> from the mode selection screen to enter this mode. Tap the <strong>&quot;Pick Color&quot;</strong> button.</p><img loading="lazy" height="386" width="751" class="common_img" src="'+j+'"><p>(2) Drag the red circle in the camera feed to the track (e.g., red tape) and tap <strong>&quot;Confirm Color&quot;.</strong></p><img loading="lazy" height="386" width="746" class="common_img" src="'+C+'"><p>(3) The selected color will be displayed under <strong>&quot;Tracking Color&quot;</strong>.</p><img loading="lazy" height="387" width="751" class="common_img" src="'+x+'"><p>(4) Tap <strong>&quot;Start&quot;</strong> to begin. The robot will follow the colored line automatically.</p><img loading="lazy" height="382" width="748" class="common_img" src="'+M+'"><ul><li><strong>QR Code Recognition</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li><p>The maximum recognition distance is approximately 35 cm (13.8 inches).</p></li><li><p>Phone brightness should be neither too dark nor too bright, as it may affect recognition accuracy.</p></li></ul></section><p>Tap <strong>&quot;QR Code Recognition&quot;</strong> to enter this mode. Tap <strong>&quot;Start&quot;</strong> to activate the feature. Select a QR code tag and hold it in front of the camera, one at a time. Once the robot recognizes the tag, it will execute the corresponding action.</p><img loading="lazy" height="288" width="1374" class="common_img" src="'+z+'"><ul><li><strong>Obstacle Avoidance</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li><p>Place the robot on a spacious surface with enough room to move freely.</p></li><li><p>Obstacles should be taller than the ultrasonic sensor for detection.</p></li></ul></section><p>Tap <strong>&quot;Obstacle Avoidance&quot;</strong> to enter the mode and tap <strong>&quot;Start&quot;</strong> to begin. The robot will move forward automatically. When it detects an obstacle, it will turn left until the path is clear, then continue moving forward.</p><img loading="lazy" height="386" width="752" class="common_img" src="'+W+'">',102)])])}const V=n(B,[["render",O]]);export{J as __pageData,V as default};
